modules.Plan=(function()
--!nocheck
-- Pure macro-plan identity, configuration, and unambiguous new-model matching.
local Plan={}
function Plan.target(entry)
    return entry.upgradeTarget==nil and 0 or entry.upgradeTarget
end
function Plan.candidate(entry,candidates,before,claimed,position,name)
    local match
    local c=entry.cframe
    for _,unit in ipairs(candidates) do
        if not before[unit] and not claimed[unit] and (not name or name(unit)) then
            local x,y,z=position(unit)
            if type(x)=="number" and (x-c[1])^2+(z-c[3])^2<=0.36 and math.abs(y-c[2])<=8 then
                if match then return nil,"AMBIGUOUS" end
                match=unit
            end
        end
    end
    return match,match and "BOUND" or "WAIT MODEL"
end
function Plan.new()
    local self={source=nil,bindings={},claimed={},active=false,token=0}
    function self:select(entries)
        if self.source~=entries then self:cancel();self.source=entries;return true end
        return false
    end
    function self:cancel()
        self.token=self.token+1;self.bindings={};self.claimed={};self.active=false
    end
    function self:start(entries)
        self:cancel();self.source=entries;self.active=true;return self.token
    end
    function self:apply(index,engine,valid,paused)
        local unit=self.bindings[index]
        if not self.active or not unit or not self.source or not self.source[index] then return false end
        if valid and not valid(unit) then return false end
        local target=Plan.target(self.source[index])
        engine:target(unit,target)
        if not paused then engine:enable(unit,target=="max" or target>0) end
        return true
    end
    function self:bind(index,unit,token)
        if not self.active or token~=self.token or self.claimed[unit] or not self.source[index] then return false end
        self.bindings[index]=unit;self.claimed[unit]=true;return true
    end
    return self
end

return Plan

end)()
