local function normal(id) return type(id)=="string" and id:lower():gsub("[{}]","") or nil end
local function first(t,keys)
    for _,key in ipairs(keys) do local v=rawget(t,key);if v~=nil then return v end end
end
local function friendly(v)
    return type(v)=="string" and #v>0 and #v<=120 and not v:find("[%c_{}]") and not v:match("^Unit #%d+$")
end
local function unitType(t,guid)
    if type(t)~="table" then return nil end
    for _,key in ipairs({"unit_id","unitId","unit_type","unitType","unit","id","modelName"}) do
        local v=rawget(t,key)
        if type(v)=="string" and #v>0 and #v<=160 and normal(v)~=guid then return v end
    end
end
Catalog.friendly=friendly
function Catalog.resolve(ids,objects,d)
    local wanted,variants,types,result={},{},{},{}
    for _,id in ipairs(ids) do
        local key=normal(id);wanted[key]=id;variants[#variants+1]={id=id,key=key}
    end
    assert(#variants<=256,"Too many unique inventory units for one catalog scan")
    local visited=0
    local function yieldIfNeeded()
        visited=visited+1
        if visited%400==0 and d.yield then d.yield() end
        if d.alive then assert(d.alive(),"Catalog scan canceled") end
    end
    local function read(def,inventoryId)
        if type(def)~="table" then return end
        local name,icon
        for _,key in ipairs({"display_name","displayName","name","Name"}) do local v=rawget(def,key);if friendly(v) then name=v;break end end
        for _,key in ipairs({"image","image_id","imageId","thumbnail","icon","portrait"}) do
            local v=rawget(def,key)
            if type(v)=="number" and v>0 and v%1==0 then v="rbxassetid://"..v end
            v=d.asset(v);if v~="" then icon=v;break end
        end
        local entry=result[inventoryId] or {}
        if name then
            entry.names=entry.names or {};entry.names[name]=true
            local count=0;for _ in pairs(entry.names) do count=count+1 end
            entry.displayName=count==1 and name or nil
        end
        if icon then
            entry.icons=entry.icons or {};entry.icons[icon]=true
            local count=0;for _ in pairs(entry.icons) do count=count+1 end
            entry.icon=count==1 and icon or nil
        end
        local model=first(def,{"model","Model","unit_model"})
        if model and d.isModel and d.isModel(model) then entry.model=model end
        result[inventoryId]=entry
    end
    -- Inventory objects can expose UUID fields or live in a UUID-keyed dictionary.
    for _,t in ipairs(objects) do
        yieldIfNeeded()
        if type(t)=="table" and not (d.ignore and d.ignore[t]) then
            local guid=normal(first(t,{"uuid","unit_uuid","unitUuid","inventory_id","UUID"}))
            if guid and wanted[guid] then
                local id=wanted[guid];types[id]=unitType(t,guid) or types[id];read(t,id)
            end
            for _,v in ipairs(variants) do
                local owned=rawget(t,v.id) or rawget(t,v.key) or rawget(t,"{"..v.key.."}")
                if type(owned)=="table" then types[v.id]=unitType(owned,v.key) or types[v.id];read(owned,v.id) end
            end
        end
    end
    -- Definitions commonly expose an id or are stored under the unit type key.
    for _,t in ipairs(objects) do
        yieldIfNeeded()
        if type(t)=="table" and not (d.ignore and d.ignore[t]) then
            local ownType=first(t,{"id","unit_id","unitId"})
            for id,key in pairs(types) do
                if ownType==key then read(t,id) end
                read(rawget(t,key),id)
            end
        end
    end
    for id,key in pairs(types) do
        result[id]=result[id] or {};result[id].modelName=key
        if not result[id].model and d.findModel then result[id].model=d.findModel(key) end
    end
    return result
end

return Catalog

end)()
