modules.StoryActions=(function()
-- Observed Story setup contract. No assumed level IDs or optional flag meanings.
local StoryActions={}
function StoryActions.new(d)
    local self={stage="idle",generation=0,enabled=false,nextAttempt=0}
    function self:tick()
        local on=d.enabled()
        if not on then
            if self.enabled then self.generation+=1;self.stage="idle";self.enabled=false end
            return
        end
        if not self.enabled then self.enabled=true;self.stage="idle";self.generation+=1 end
        if not d.alive() or d.broker.pending or d.broker.blocked or d.clock()<self.nextAttempt or self.stage=="done" or self.stage=="blocked" then return end
        local allowed,reason,config=d.configuration()
        config=config or {friends=false,match=false}
        if not allowed then self.stage="blocked";d.report(reason);return end
        if config.match then
            if self.stage=="idle" then self.stage="match" end
            if self.stage~="match" then self.stage="blocked";d.report("Story: turn both auto switches off before changing mode");return end
            local ready,message=d.readyMatch()
            if not ready then self.nextAttempt=d.clock()+2;d.report(message);return end
        elseif self.stage=="match" then self.stage="blocked";d.report("Story: turn both auto switches off before changing mode");return end
        if self.stage=="idle" then
            self.lobby=d.candidate()
            if not self.lobby then self.nextAttempt=d.clock()+3;d.report("Story: waiting for an available lobby");return end
            self.stage="join"
        end
        if self.stage~="match" and not d.exists(self.lobby) then self.stage="blocked";d.report("Story lobby removed; toggle Auto Join off/on");return end
        local action=self.stage
        local remoteName=action=="match" and "request_matchmaking" or action=="join" and "request_join_lobby" or action=="lock" and "request_lock_level" or "request_start_game"
        local remote=d.remote(remoteName)
        if not remote then self.nextAttempt=d.clock()+3;d.report("Story: waiting for "..remoteName);return end
        local token=self.generation
        local call={done=false};d.broker.pending=call
        d.spawn(function()
            local result
            if action=="match" then result=table.pack(pcall(d.invoke,remote,"namek_infinite"))
            elseif action=="lock" then result=table.pack(pcall(d.invoke,remote,self.lobby,"namek_level_1",config.friends==true,"Normal"))
            else result=table.pack(pcall(d.invoke,remote,self.lobby)) end
            call.done=true
            if d.broker.pending==call then d.broker.pending=nil end
            if not d.alive() or not d.enabled() or token~=self.generation then return end
            if not result[1] then self.stage="blocked";d.report("Story call failed: "..tostring(result[2]));return end
            if action=="match" then
                self.stage="done"
                d.report(result[2]==false and "Find Match refused; toggle off/on to retry" or "Find Match sent; waiting for matchmaking")
            elseif action=="start" then
                self.stage="done"
                d.report(result[2]==false and "Story start refused; toggle Auto Join off/on" or "Story start sent; waiting for teleport")
            elseif result[2]==true then
                self.stage=action=="join" and "lock" or "start";self.nextAttempt=d.clock()+1
                d.report(action=="join" and "Story lobby joined" or "Story level selected")
            else self.stage="blocked";d.report("Story "..action.." not confirmed; toggle Auto Join off/on") end
        end)
    end
    return self
end
return StoryActions

end)()
