modules.MatchActions=(function()
-- Confirmed votes only; a returned call is not proof that a vote passed.
local MatchActions={}
function MatchActions.new(d)
    local self={sent={},nextAttempt=0}
    function self:tick()
        if not d.alive() or d.broker.pending or d.broker.blocked or d.clock()<self.nextAttempt then return end
        local started,wave=d.state()
        if type(started)~="boolean" or type(wave)~="number" then return end
        local name,key
        if not started and d.enabled("start") and d.visible("VoteStart") then name="vote_start";key="start"
        elseif started and wave>=1 and d.enabled("skip") and d.visible("VoteSkip") then name="vote_wave_skip";key="skip:"..wave end
        if not key or self.sent[key] then return end
        local remote=d.remote(name);if not remote then return end
        self.sent[key]=true
        local call={done=false};d.broker.pending=call
        d.spawn(function()
            local result=table.pack(pcall(d.invoke,remote))
            call.done=true
            if d.broker.pending==call then d.broker.pending=nil end
            if not d.alive() then return end
            self.nextAttempt=d.clock()+3
            if not result[1] then d.report("Match vote failed: "..tostring(result[2]));return end
            if result[2]==false then self.sent[key]=nil;d.report("Match vote refused; waiting")
            else d.report("Match vote sent; waiting for game state") end
        end)
    end
    return self
end
return MatchActions

end)()
