modules.Motion=(function()
-- Client-only navigation cosmetics. No gameplay or remote dependencies.
local Motion = {}
function Motion.new(tweens, reduced, delay)
    local self = {generation=0, active={}, restore={}, alive=true}
    function self:cancel()
        self.generation+=1
        for _,t in ipairs(self.active) do t:Cancel();t:Destroy() end
        self.active={}
        for _,entry in ipairs(self.restore) do
            if entry.object.Parent then
                for key,value in pairs(entry.goal) do entry.object[key]=value end
            end
        end
        self.restore={}
    end
    function self:play(object,goal,duration)
        local t=tweens:Create(object,TweenInfo.new(duration,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),goal)
        self.active[#self.active+1]=t;t:Play()
    end
    function self:enter(highlight,row,blocks,first)
        local previous=highlight and highlight.AbsolutePosition
        self:cancel()
        local token=self.generation
        if highlight then
            highlight.Parent=row
            highlight.AnchorPoint=Vector2.new(0,0)
            highlight.Size=UDim2.fromScale(1,1)
        end
        local instant=first or reduced()
        if highlight then highlight.Position=UDim2.fromScale(0,0) end
        if highlight and not instant and row.AbsoluteSize.X>0 and row.AbsoluteSize.Y>0 then
            highlight.Position=UDim2.fromScale((previous.X-row.AbsolutePosition.X)/row.AbsoluteSize.X,
                (previous.Y-row.AbsolutePosition.Y)/row.AbsoluteSize.Y)
            self:play(highlight,{Position=UDim2.fromScale(0,0)},0.22)
        end
        if instant then return end
        -- Fade the original instances; preserve layouts, hit targets and model hierarchy.
        for index,block in ipairs(blocks) do
            local entries={}
            local objects=block:GetDescendants();table.insert(objects,1,block)
            for _,object in ipairs(objects) do
                local goal={}
                if object:IsA("GuiObject") then goal.BackgroundTransparency=object.BackgroundTransparency end
                if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                    goal.TextTransparency=object.TextTransparency;goal.TextStrokeTransparency=object.TextStrokeTransparency
                end
                if object:IsA("ImageLabel") or object:IsA("ImageButton") then goal.ImageTransparency=object.ImageTransparency end
                if object:IsA("UIStroke") then goal.Transparency=object.Transparency end
                if next(goal) then
                    local entry={object=object,goal=goal}
                    entries[#entries+1]=entry;self.restore[#self.restore+1]=entry
                    for key in pairs(goal) do object[key]=1 end
                end
            end
            delay((index-1)*0.055,function()
                if not self.alive or token~=self.generation then return end
                for _,entry in ipairs(entries) do
                    if entry.object.Parent then self:play(entry.object,entry.goal,self.duration or 0.24) end
                end
            end)
        end
        delay((self.duration or 0.24)+math.max(0,#blocks-1)*0.055,function()
            if self.alive and token==self.generation then self:cancel();if highlight then highlight.Position=UDim2.fromScale(0,0) end end
        end)
    end
    function self:destroy() self.alive=false;self:cancel() end
    return self
end
return Motion

end)()
