        configuration=function()
            local world=nodes[548].Text:lower():match("^%s*(.-)%s*$")
            local act=nodes[555].Text:lower():match("^%s*(.-)%s*$")
            local difficulty=nodes[562].Text:lower():match("^%s*(.-)%s*$")
            if world~="planet greenie" and world~="namek" then return false,"Story: only Planet Greenie is connected" end
            if mainState.values["593"]==true then
                if act~="infinite" then return false,"Find Match: set Act to Infinite" end
                if mainState.values["567"]==true then return false,"Find Match + Friends Only is not confirmed; turn Friends Only off" end
                return true,nil,{match=true}
            end
            if act~="act 1" and act~="1" then return false,"Story: only Act 1 is confirmed" end
