        end,
        candidate=function()
            local folder=storyFolder();if not folder then return nil end
            local candidates=folder:GetChildren();table.sort(candidates,function(a,b) return a.Name<b.Name end)
            for _,lobby in ipairs(candidates) do
                local active=lobby:FindFirstChild("Active");local level=lobby:FindFirstChild("Level")
                if lobby.Name:match("^_lobbytemplategreen%d+$") and active and active:IsA("BoolValue") and not active.Value
                    and level and level:IsA("StringValue") and level.Value=="" then return lobby.Name end
            end
        end,
        exists=function(name) local folder=storyFolder();return folder and folder:FindFirstChild(name)~=nil end,
        remote=function(name)
            local endpoints=RS:FindFirstChild("endpoints")
            local folder=endpoints and endpoints:FindFirstChild("client_to_server")
            local remote=folder and folder:FindFirstChild(name)
            return remote and remote:IsA("RemoteFunction") and remote or nil
        end,
        invoke=function(remote,...) return remote:InvokeServer(...) end,
        report=function(message) nodes[632].Text=message end,
    })
    runtime.storyActions=storyActions
    task.spawn(function()
        while runtime.alive do
            local ok,err=pcall(function() storyActions:tick() end)
            if not ok then nodes[632].Text="Story: "..tostring(err):sub(1,100) end
            task.wait(0.4)
        end
    end)


    return {}
end
return MainActionsController

end)()
-- Module: src/infrastructure/Storage.lua
modules.Storage=(function()
--!nocheck
local Storage={}
function Storage.mount(context)
    local Http=assert(context.Http,"Storage: missing Http")
    local maxBytes=assert(context.maxBytes,"Storage: missing maxBytes")
    local function storage()
        assert(type(writefile)=="function" and type(readfile)=="function" and type(isfile)=="function",
            "writefile/readfile/isfile unavailable")
    end
    local function readJSON(path)
        storage()
        assert(isfile(path), "File not found: " .. path)
        local raw = readfile(path)
        assert(type(raw)=="string" and #raw <= maxBytes, "File too large")
        return Http:JSONDecode(raw)
    end
    local function writeJSON(path, doc)
        storage()
        local raw = Http:JSONEncode(doc)
        assert(#raw <= maxBytes, "File too large")
        if isfile(path) then
            local previous = readfile(path)
            assert(type(previous)=="string" and #previous <= maxBytes, "Previous file too large")
            writefile(path..".bak",previous)
            assert(readfile(path..".bak")==previous,"Backup verification failed")
        end
        writefile(path, raw)
        assert(readfile(path)==raw,"Write verification failed; check .bak")
    end

    return {available=storage,readJSON=readJSON,writeJSON=writeJSON}
end
return Storage

end)()
