modules.ToggleAnimator=(function()
--!nocheck
local ToggleAnimator={}
function ToggleAnimator.mount(context)
    local entranceMotion=assert(context.entranceMotion,"ToggleAnimator: missing entranceMotion")
    local switchTweens,switchGoals={},{}
    local function switchVisual(object,property,goal,animated)
        if not object then return end
        local previous=switchGoals[object] or {}
        if previous[property]==goal then return end
        previous[property]=goal;switchGoals[object]=previous
        local active=switchTweens[object] or {};switchTweens[object]=active
        if active[property] then active[property]:Cancel();active[property]:Destroy();active[property]=nil end
        local reduced=false
        pcall(function() reduced=game:GetService("GuiService").ReducedMotionEnabled end)
        if not animated or reduced then object[property]=goal;return end
        entranceMotion:cancel()
        local tween=game:GetService("TweenService"):Create(object,
            TweenInfo.new(0.2,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{[property]=goal})
        active[property]=tween;tween:Play()
    end

    local function destroy()
        for _,properties in pairs(switchTweens) do
            for _,tween in pairs(properties) do tween:Cancel();tween:Destroy() end
        end
        table.clear(switchTweens);table.clear(switchGoals)
    end

    return {set=switchVisual,destroy=destroy,active=switchTweens,goals=switchGoals}
end
return ToggleAnimator

end)()
