    local function text(en, ru) return settings.language == "Russian" and ru or en end
    local function connect(signal, fn, bucket)
        local c = signal:Connect(fn)
        table.insert(bucket or runtime.connections, c)
        return c
    end
    local function report(message)
        lastMessage = tostring(message)
        if refresh and runtime.alive then refresh() end
        print("[GH AAUI] " .. lastMessage)
    end
    local function safe(fn)
        return function(...)
            if not runtime.alive then return end
            local ok, err = pcall(fn, ...)
            if not ok then report(err) end
        end
    end
    local function bind(button, fn) connect(button.Activated, safe(fn)) end
    local function confirmAction(key, value)
        local now = os.clock()
        local previous = confirm[key]
        if previous and previous.value == value and now <= previous.untilTime then
            confirm[key] = nil
            return true
        end
        confirm[key] = {value = value, untilTime = now + 5}
        report(text("Press again within 5 seconds to confirm: ", "Нажми ещё раз за 5 секунд: ") .. key)
        return false
    end
    local files=Storage.mount({Http=Http,maxBytes=maxBytes})
    local storage,readJSON,writeJSON=files.available,files.readJSON,files.writeJSON
    local function validName(name)
        assert(type(name)=="string", "Invalid macro name")
        name = name:match("^%s*(.-)%s*$")
        assert(#name>0 and #name<=48 and not name:find("[%c/\\]"), "Name: 1..48 bytes, no slashes/control characters")
        return name
    end
    local function macroPath(name)
        local encoded = validName(name):gsub(".",function(c) return string.format("%02x",string.byte(c)) end)
        return prefix .. "macro_" .. encoded .. ".json"
    end
    local function contains(t, value)
        for _, v in ipairs(t) do if v==value then return true end end
        return false
    end
    local function validateNames(doc)
        assert(type(doc)=="table" and doc.version==1,"Invalid catalog")
        local result={}
        for i=1,Recorder.array(doc.names,100) do
            local name=validName(doc.names[i])
            assert(not contains(result,name),"Duplicate name in catalog")
            table.insert(result,name)
        end
        table.sort(result)
        return result
    end
    local function saveCatalog()
        writeJSON(prefix.."index.json",{version=1,names=savedNames})
    end
    local function findRemote()
        local a=RS:FindFirstChild("endpoints")
        local b=a and a:FindFirstChild("client_to_server")
        local c=b and b:FindFirstChild("spawn_unit")
        return c and c:IsA("RemoteFunction") and c or nil
    end
    core = Recorder.new({broker=broker,placeId=game.PlaceId,userId=player.UserId,
        clock=os.clock,spawn=task.spawn,wait=task.wait,remote=function() local r=findRemote();broker.captureRemote=r;return r end,
        canRecord=function() return broker.installed==true end,
        invoke=function(remote,id,components) return remote:InvokeServer(id,CFrame.new(table.unpack(components))) end,
        describe=function(values)
            local parts={}
            for i=1,math.min(values.n,3) do
                local value=values[i]
                local kind=typeof(value)
                local encoded
                if kind=="table" then
                    local ok,json=pcall(function() return Http:JSONEncode(value) end)
                    encoded=ok and json or "<table>"
                else encoded=tostring(value) end
                parts[#parts+1]=kind..":"..tostring(encoded):sub(1,180)
            end
            return #parts>0 and table.concat(parts," | ") or "no return values"
        end,
        changed=report,
        selecting=function() if runtime.cancelUpgrades then runtime.cancelUpgrades() end end,
        recordStart=function(owner) if runtime.recordStart then runtime.recordStart(owner) end end,
        recorded=function(owner,entry,index) if runtime.recorded then runtime.recorded(owner,entry,index) end end,
        playStart=function(owner,entries,generation) if runtime.playStart then runtime.playStart(owner,entries,generation) end end,
        beforePlacement=function(owner,entry,index,generation) if runtime.beforePlacement then return runtime.beforePlacement(owner,entry,index,generation) end end,
        latePlaced=function(owner,entry,index,generation,context) if runtime.placed then runtime.placed(owner,entry,index,generation,context) end end,
        placed=function(owner,entry,index,generation,context) if runtime.placed then runtime.placed(owner,entry,index,generation,context) end end,
    })
    if old and type(old.entries)=="table" and #old.entries>0 then
        local ok,err=pcall(function()
            core:replace({format="AAPlacementRecorder",version=1,placeId=game.PlaceId,userId=player.UserId,entries=old.entries})
            core.dirty=true; n(96).Text="Recovered v1"
        end)
        if not ok then report("v1 memory was not migrated: "..tostring(err)) end
    end
    local function saveMacro()
        core:idle()
        local name = validName(n(96).Text)
        assert(contains(savedNames,name) or #savedNames<100,"Maximum 100 saved macros")
        local doc=core:document()
        Recorder.validate(doc,doc.placeId,player.UserId)
        writeJSON(macroPath(name),doc)
        if not contains(savedNames,name) then table.insert(savedNames,name); table.sort(savedNames) end
        core.dirty=false
        selectedName=name
        saveCatalog()
        report(text("Saved: ","Сохранено: ")..name)
    end
    local function loadMacro(name, legacy)
        core:idle()
        if core.dirty and #core.entries>0 and not confirmAction("replace recording",name) then return end
        local doc=readJSON(legacy and "AA_PlacementRecorder_v1.json" or macroPath(name))
        core:replace(doc)
        selectedName, n(96).Text = name,name
        report(text("Loaded: ","Загружено: ")..name)
    end
    local function deleteMacro()
        core:idle()
        local name=validName(n(96).Text)
        assert(contains(savedNames,name),"Pick a saved macro to delete")
        assert(type(delfile)=="function","delfile unavailable")
        if not confirmAction("delete "..name,name) then return end
        storage()
        local path=macroPath(name)
        if isfile(path) then
            local raw=readfile(path)
            assert(type(raw)=="string" and #raw<=maxBytes,"File too large")
            writefile(path..".bak",raw)
            assert(readfile(path..".bak")==raw,"Backup verification failed")
            delfile(path)
            assert(not isfile(path),"Delete failed")
        end
        local remaining={}
        for _,v in ipairs(savedNames) do if v~=name then table.insert(remaining,v) end end
        savedNames=remaining
        saveCatalog()
        selectedName=""
        report(text("Saved file deleted; current memory recording retained", "Файл удалён; запись в памяти сохранена"))
    end

