    local function validateSettings(doc)
        assert(type(doc)=="table" and doc.format=="GHAAUISettings" and doc.version==1,"Invalid settings format")
        local s=doc.settings; assert(type(s)=="table","Invalid settings")
        assert(s.language=="English" or s.language=="Russian","Unsupported language")
        for key,range in pairs({scale={60,140},opacity={35,100},delay={300,5000}}) do
            assert(Recorder.finite(s[key]) and s[key]%1==0 and s[key]>=range[1] and s[key]<=range[2],"Invalid "..key)
        end
        assert(type(s.autoHide)=="boolean" and type(s.autoLoad)=="boolean","Invalid toggle")
        assert(type(s.hotkey)=="string" and #s.hotkey<=32,"Invalid hotkey")
        local ok,key=pcall(function() return Enum.KeyCode[s.hotkey] end)
        assert(ok and key and key~=Enum.KeyCode.Unknown and key~=Enum.KeyCode.Escape,"Invalid hotkey")
        local clean={}
        for k in pairs(settings) do clean[k]=s[k] end
        return clean
    end
    local function settingsDoc(s)
        return {format="GHAAUISettings",version=1,settings=s or settings}
    end
