    local switchInitialized={}
    local function switch(track,fill,knob,enabled)
        local animate=switchInitialized[track]==true
        switchVisual(n(fill),"BackgroundTransparency",enabled and (1-settings.opacity/100) or 1,animate)
        switchVisual(n(knob),"Position",UDim2.new(0,enabled and 26 or 10,0.5,0),animate)
