    local function fitScale()
        local camera=workspace.CurrentCamera
        local size=camera and camera.ViewportSize or Vector2.new(1024,768)
        n(25).Scale=math.max(0.1,math.min(settings.scale/100,(size.X-24)/760,(size.Y-24)/500))
    end
    refresh=function()
        if not runtime.alive then return end
        local mode=core.mode
        n(90).Text=text("MACRO · ","МАКРОС · ")..mode
        n(98).Text=mode=="REC" and text("STOP REC","СТОП ЗАПИСЬ") or text("Record Macro","Записать")
        n(102).Text=text("Delete Macro","Удалить файл")
        n(110).Text=mode=="PLAY" and text("Stop Playback","Стоп воспроизведение") or text("Play Macro","Воспроизвести")
        n(184).Text=lastMessage; n(184).TextTruncate=Enum.TextTruncate.AtEnd
        n(187).Text=core.step.." / "..#core.entries..(core.waiting and (" · retry "..core.attempt) or "")
        n(388).RichText=false
        n(388).Text=(core.waiting and "WAIT" or mode).." · "..(core.dirty and "* " or "")..lastMessage
        n(388).TextTruncate=Enum.TextTruncate.AtEnd
        n(124).Text=selectedName~="" and selectedName or text("Select...","Выбрать...")
