        if popup then
            if input.KeyCode==Enum.KeyCode.Escape then closePopup(); return end
            if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
                local p,size=popup.AbsolutePosition,popup.AbsoluteSize
                local point=input.Position
                if point.X<p.X or point.Y<p.Y or point.X>p.X+size.X or point.Y>p.Y+size.Y then closePopup() end
            end
        end
        if UIS:GetFocusedTextBox() then return end
        if keyCapture then
            if input.KeyCode==Enum.KeyCode.Escape then keyCapture=nil; refresh(); return end
            if input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode~=Enum.KeyCode.Unknown then
                settings.hotkey=input.KeyCode.Name; keyCapture=nil; changedSettings()
            end
            return
        end
        if processed then return end
        if input.KeyCode.Name==settings.hotkey then
            if n(22).Visible then runtime.hide() else runtime.show() end
        elseif input.KeyCode==Enum.KeyCode.Escape then closePopup() end
    end))
