        if obj:IsA("GuiObject") then props.BackgroundTransparency=obj.BackgroundTransparency end
        if obj:IsA("TextButton") then props.TextTransparency=obj.TextTransparency; props.TextStrokeTransparency=obj.TextStrokeTransparency end
        if obj:IsA("UIStroke") then props.Transparency=obj.Transparency end
        baseTransparency[obj]=props
    end
    local function validatePresets(doc)
        assert(type(doc)=="table" and doc.version==1,"Invalid presets file")
        local clean={}
        for i=1,Recorder.array(doc.presets,30) do
            local v=doc.presets[i]; assert(type(v)=="table","Invalid preset")
            local name=validName(v.name)
            assert(not clean[name],"Duplicate preset")
            clean[name]=validateSettings(v.document)
        end
        return clean
    end
    bind(profileButtons[1],function()
        local name=validName(n(306).Text)
        local count=0; for _ in pairs(presets) do count=count+1 end
        assert(presets[name] or count<30,"Maximum 30 UI presets")
        local clean=validateSettings(settingsDoc())
        local newPresets={}; for key,value in pairs(presets) do newPresets[key]=value end
        newPresets[name]=clean
        local entries={}; for key,value in pairs(newPresets) do table.insert(entries,{name=key,document=settingsDoc(value)}) end
        writeJSON(prefix.."presets.json",{version=1,presets=entries})
        presets=newPresets
        report(text("UI preset saved: ","Профиль UI сохранён: ")..name)
    end)
    bind(profileButtons[2],function()
        local options={}
        for name,preset in pairs(presets) do
            local picked=preset
            table.insert(options,{label=name,run=function()
                local clean=validateSettings(settingsDoc(picked))
                -- Local preset loading does not enable teleport execution implicitly.
                clean.autoLoad=false
                settings=clean; n(306).Text=name; changedSettings()
                report(text("UI preset loaded", "Профиль UI загружен"))
            end})
        end
        table.sort(options,function(a,b) return a.label<b.label end)
        dropdown(profileButtons[2],options)
    end)
    n(309).Text="UI profiles stay local. Exchange settings using CONFIG CODE."

    runtime.unload=function()
        if not runtime.alive then return end
        runtime.alive=false
        entranceMotion:destroy()
        navigationMotion:destroy()
        toggleAnimator.destroy()
        core:destroy(); broker.capture=nil;broker.peek=nil
        closePopup(); dragging=nil;navigation.stopDrag()
        runtime.alive=false
        for _,c in ipairs(runtime.connections) do c:Disconnect() end
        runtime.connections={}
        gui:Destroy()
        env[runtimeKey]=nil
        -- Keep the passive broker wrapper: restoring it could overwrite another tool's hook.
    end
    bind(n(349),function()
        if core.dirty and #core.entries>0 and not confirmAction("unload unsaved recording",tostring(core.generation)) then return end
        runtime.unload()
    end)
    connect(gui.Destroying,function() if runtime.alive then runtime.unload() end end)
    env[runtimeKey]=runtime
    setTab("Macro")
    gui.ResetOnSpawn=false
    gui.DisplayOrder=100
    n(22).Visible=false
    gui.Parent=assert(player:WaitForChild("PlayerGui",10),"PlayerGui unavailable")
    local function loadOptional(path, apply)
        if type(isfile)~="function" or not isfile(path) then return end
        local ok,err=pcall(function() apply(readJSON(path)) end)
        if not ok then report("Ignored invalid saved file: "..tostring(err)) end
    end
    loadOptional(prefix.."index.json",function(doc) savedNames=validateNames(doc) end)
    loadOptional(prefix.."settings.json",function(doc) settings=validateSettings(doc) end)
    loadOptional(prefix.."presets.json",function(doc) presets=validatePresets(doc) end)
    if type(queueAPI)~="function" or type(isfile)~="function" or not isfile(Config.FILENAME) then settings.autoLoad=false end
    if not broker.installed then
        if type(hookmetamethod)=="function" and type(getnamecallmethod)=="function" and type(newcclosure)=="function" then
            local original
            local ok,err=pcall(function()
                original=hookmetamethod(game,"__namecall",newcclosure(function(self,...)
                    local method=getnamecallmethod()
                    -- Only pure Lua checks before original dispatch: engine introspection
                    -- can corrupt the executor's namecall method (diagnosed in v2).
                    if method=="InvokeServer" and broker.peek and broker.peek(self) then
                        local args=table.pack(...)
                        task.defer(function()
                            if broker.capture then pcall(broker.capture,self,table.unpack(args,1,args.n)) end
                        end)
                    end
                    return original(self,...)
                end))
            end)
            broker.installed=ok
            if not ok then report("Capture hook unavailable: "..tostring(err)) end
        else
            report("Capture APIs unavailable; menu and file tools remain available")
        end
    end
    broker.peek=function(remote) return core.mode=="REC" and remote==broker.captureRemote end
    broker.capture=function(remote,...)
        if core.mode~="REC" or remote~=findRemote() then return end
        local id,cf=...
        if typeof(cf)~="CFrame" then core:stop(); report("Invalid spawn_unit CFrame"); return end
        core:capture(id,{cf:GetComponents()},select("#",...))
    end
    applySettings()
    local cameraConnection
    local function watchCamera()
        if cameraConnection then cameraConnection:Disconnect() end
        local camera=workspace.CurrentCamera
        if camera then cameraConnection=connect(camera:GetPropertyChangedSignal("ViewportSize"),fitScale) end
        fitScale()
    end
    connect(workspace:GetPropertyChangedSignal("CurrentCamera"),watchCamera)
    watchCamera()
    local previousRemote=findRemote()
    task.spawn(function()
        while runtime.alive do
            task.wait(0.5)
            if not runtime.alive then return end
            local current=findRemote()
            if settings.autoHide and current and current~=previousRemote then runtime.hide() end
            previousRemote=current
        end
    end)
    if settings.autoHide and findRemote() then runtime.hide() end
    report(findRemote() and text("Ready · placement + Auto Upgrade", "Готово · размещения и автоулучшения") or text("Menu ready; join a match to record", "Меню готово; войди в матч для записи"))


    AutoUpgradeController.mount({baseTransparency=baseTransparency,runtime=runtime,core=core,broker=broker,player=player,RS=RS,
        nodes=nodes,legacyNodes=legacyNodes,bindingMap=bindingMap,Recorder=Recorder,Plan=Plan,
        Upgrader=Upgrader,Catalog=Catalog,Portrait=Portrait,n=n,extra=extra,settings=settings,
        connect=connect,bind=bind,safe=safe,text=text,report=report,confirmAction=confirmAction})
    local mainState=MainSettingsController.mount({runtime=runtime,player=player,nodes=nodes,prefix=prefix,
        readJSON=readJSON,writeJSON=writeJSON,report=report,connect=connect,safe=safe,bind=bind,
        dropdown=dropdown,navigationMotion=navigationMotion,switchVisual=switchVisual})
    MainActionsController.mount({runtime=runtime,mainState=mainState,broker=broker,nodes=nodes,
        player=player,RS=RS,MatchActions=MatchActions,StoryActions=StoryActions})
    -- Reveal only after all controls, settings and adapters have initialized.
    task.defer(function()
        if runtime.alive and not (settings.autoHide and findRemote()) then runtime.show() end
    end)

    -- APP_TEST_INSERTION_POINT
    return runtime
end
return App

end)()
modules.App.start(modules)
